// compiled with gcc -O2 for x86-64
long total(long price, long qty, long tax) {
    return price * qty + tax;
}

#define N 4096
int grid[N][N];  // stored row by row

long fast(void) {      // ~0.01 s
    long sum = 0;
    for (int r = 0; r < N; r++)
        for (int c = 0; c < N; c++)
            sum += grid[r][c]; // +4 B
    return sum;
}

long slow(void) {      // ~0.12 s
    long sum = 0;
    for (int c = 0; c < N; c++)
        for (int r = 0; r < N; r++)
            sum += grid[r][c]; // +16 KB
    return sum;
}

